// Create a new base mutator instance via default constructor.
protobuf_mutator::Mutator *mutator = new protobuf_mutator::Mutator();

// Track seeding state for downstream stubs.
FUZZ_SET_ATTR_INT(mutator, "seeded", 0);
FUZZ_SET_ATTR_INT(mutator, "seed", 0);

// Validation: object is non-null and owned by the fuzzer pool via outputs.
// If allocation failed (extremely unlikely in this harness), bail.
if (!mutator) { FUZZ_BAIL(); }

// Validation summary: Constructs a fresh Mutator and annotates it as unseeded; the object is returned to the pool.

// Destroy the mutator. No additional ownership is tracked in the API.
// Drop any attributes; memory is released by delete.
if (!mutator) { FUZZ_BAIL(); }

// It is safe to delete regardless of seeded state.
delete mutator;

// Validation summary: Ensures non-null then deletes; no outputs are returned to avoid use-after-free.

// Seed must be any 32-bit unsigned integer.
if (!mutator) { FUZZ_BAIL(); }
uint32_t seed = (uint32_t)(*FUZZ_PARAM(unsigned int));

// Initialize internal RNG for deterministic behavior.
mutator->Seed(seed);

// Track seeding metadata for later operations.
FUZZ_SET_ATTR_INT(mutator, "seeded", 1);
FUZZ_SET_ATTR_INT(mutator, "seed", (int)seed);

// Keep mutator alive by returning it as an output.
// Validation summary: Non-null input, calls Seed with a valid 32-bit value, and persists the object with seed metadata.

// Query the compile-time capability and assert it is a proper boolean value.
bool can_set = protobuf_mutator::TextParserCanSetRecursionLimit();
FUZZ_ASSERT((can_set == true) || (can_set == false), "constexpr capability must be boolean");
// Record in global attributes for potential cross-stub checks.
FUZZ_SET_ATTR_INT_GLOBAL("TextParserCanSetRecursionLimit", can_set ? 1 : 0);
// Validation: No inputs/outputs; call is pure/constexpr and side-effect free. We assert boolean-ness and store a hint for other stubs.

// Query the compile-time capability and assert it is a proper boolean value.
bool can_allow = protobuf_mutator::TextParserCanAllowUnknownField();
FUZZ_ASSERT((can_allow == true) || (can_allow == false), "constexpr capability must be boolean");
// Cross-check expected relationship: allowing unknown fields implies the parser supports
// setting recursion limit on versions where this is enabled (>= 3.8 typically sets both).
bool can_set = protobuf_mutator::TextParserCanSetRecursionLimit();
if (can_allow) {
  FUZZ_ASSERT(can_set, "AllowUnknownField implies SetRecursionLimit support in supported protobuf versions");
}
// Validation: No inputs/outputs; pure constexpr calls. We assert boolean-ness and a logical implication between capabilities.
